<body>
  <header>
    <h1>
      <span class="accent-glow">ðŸŒ€ Codebase Harmonizer</span>
      <span class="badge">v3.0 Â· 3-way intelligent merge</span>
    </h1>
    <div class="toolbar">
      <button id="btnMerge"><span>âš¡</span> Merge & Refactor</button>
      <button id="btnClearAll"><span>ðŸ§¹</span> Clear All</button>
      <button id="btnLoadSample"><span>ðŸ“¦</span> Load Sample</button>
      <button id="btnAcceptBest"><span>ðŸ§ </span> Autoâ€‘Accept Best</button>
    </div>
  </header>

  <div class="grid-3col">
    <!-- BASE version (common ancestor) -->
    <div class="panel">
      <div class="panel-header">
        <span>ðŸ“œ BASE <span class="merge-label">common ancestor</span></span>
        <span>v0</span>
      </div>
      <textarea id="baseEditor" placeholder="// Paste the base / original code..."></textarea>
    </div>
    <!-- OURS version -->
    <div class="panel">
      <div class="panel-header">
        <span>ðŸ”· OURS <span class="merge-label">current branch</span></span>
        <span>feature/ours</span>
      </div>
      <textarea id="oursEditor" placeholder="// Paste your version (ours)..."></textarea>
    </div>
    <!-- THEIRS version -->
    <div class="panel">
      <div class="panel-header">
        <span>ðŸ”¶ THEIRS <span class="merge-label">incoming fork</span></span>
        <span>feature/theirs</span>
      </div>
      <textarea id="theirsEditor" placeholder="// Paste their version (theirs)..."></textarea>
    </div>
  </div>

  <!-- Merged output panel (full width below) -->
  <div style="display: flex; flex-direction: column; margin-top: 0.5rem; gap: 0.5rem;">
    <div class="panel" style="flex: 0 0 auto; max-height: 38vh;">
      <div class="panel-header">
        <span>âœ¨ HARMONIZED MERGE <span style="font-size:0.7rem;">(resolved conflicts shown)</span></span>
        <span id="conflictCount" class="conflict-indicator">0 conflicts</span>
      </div>
      <textarea id="mergedEditor" class="merged-output" readonly placeholder="Merged result will appear here..." style="min-height: 150px;"></textarea>
    </div>
    <div class="footer-actions">
      <div class="status-message" id="statusMsg">
        <span>ðŸ’¾</span> Ready to synthesize. Paste code above and click Merge.
      </div>
      <button id="btnCopyMerged"><span>ðŸ“‹</span> Copy Merged Result</button>
    </div>
  </div>

  <script>
    (function() {
      // ----- state & references -----
      const dmp = new diff_match_patch();

      const baseEl = document.getElementById('baseEditor');
      const oursEl = document.getElementById('oursEditor');
      const theirsEl = document.getElementById('theirsEditor');
      const mergedEl = document.getElementById('mergedEditor');
      const conflictCountSpan = document.getElementById('conflictCount');
      const statusMsg = document.getElementById('statusMsg');

      // ----- localStorage persistence -----
      function saveToStorage() {
        const state = {
          base: baseEl.value,
          ours: oursEl.value,
          theirs: theirsEl.value,
          merged: mergedEl.value
        };
        localStorage.setItem('harmonizer_state', JSON.stringify(state));
      }

      function loadFromStorage() {
        const saved = localStorage.getItem('harmonizer_state');
        if (saved) {
          try {
            const state = JSON.parse(saved);
            baseEl.value = state.base || '';
            oursEl.value = state.ours || '';
            theirsEl.value = state.theirs || '';
            mergedEl.value = state.merged || '';
            updateConflictCountFromMerged();
          } catch (e) {}
        }
      }

      // Auto-save on input
      [baseEl, oursEl, theirsEl].forEach(el => {
        el.addEventListener('input', () => {
          saveToStorage();
        });
      });

      // ----- Merge logic using diff-match-patch 3-way -----
      function performMerge() {
        const base = baseEl.value;
        const ours = oursEl.value;
        const theirs = theirsEl.value;

        if (!base && !ours && !theirs) {
          mergedEl.value = '// Awaiting code versions...';
          conflictCountSpan.textContent = '0 conflicts';
          statusMsg.innerHTML = '<span>âš ï¸</span> All editors empty. Paste code to merge.';
          return;
        }

        // Use diff_match_patch's built-in 3-way merge (line-mode via patch)
        // dmp.patch_make computes patches from base->ours and base->theirs, then merges.
        const patchesOurs = dmp.patch_make(base, ours);
        const patchesTheirs = dmp.patch_make(base, theirs);

        // Combine patches: apply ours then theirs onto base. Conflicts might appear as rejections.
        // But we want a unified diff with conflict markers. Let's do text-level merge using diff_linesToChars.
        const [lineText1, lineText2, lineText3] = dmp.diff_linesToChars_(base, ours, theirs);
        const diffs = dmp.diff_main(lineText1, lineText2, false);
        dmp.diff_charsToLines_(diffs, lineText3);

        // Actually, diff_linesToChars_ returns object with chars1, chars2, lineArray. We'll use a simpler approach:
        // Compute line-mode diffs for base->ours and base->theirs, then merge using common patch apply.
        const [mergedText, conflictStatus] = dmp.patch_apply(dmp.patch_make(base, ours, theirs), base);
        // patch_make with three args creates combined patches. If conflicts, patch_apply returns [text, results[]]
        // results is array of booleans. We'll count false as conflicts.
        const conflictResults = conflictStatus.filter(v => v === false).length;

        // But that might not show conflict markers. For explicit conflict visualization, we'll use a custom merge with markers.
        const customMerged = threeWayMergeWithMarkers(base, ours, theirs);

        mergedEl.value = customMerged.text;
        conflictCountSpan.textContent = `${customMerged.conflictCount} conflict(s)`;
        if (customMerged.conflictCount > 0) {
          conflictCountSpan.className = 'conflict-indicator';
          statusMsg.innerHTML = '<span>âš ï¸</span> Conflicts detected. Resolve manually in merged view or use Auto-Accept.';
        } else {
          conflictCountSpan.className = 'save-indicator';
          statusMsg.innerHTML = '<span>âœ…</span> Clean merge â€” no conflicts.';
        }
        saveToStorage();
        updateConflictCountFromMerged();
      }

      // 3-way merge with <<<<<<<, =======, >>>>>>> markers
      function threeWayMergeWithMarkers(base, ours, theirs) {
        const baseLines = base.split('\n');
        const oursLines = ours.split('\n');
        const theirsLines = theirs.split('\n');

        // Simple line-by-line LCS merge (myers diff) - we'll use dmp for line diffs
        const dmpLine = new diff_match_patch();
        // Compute diff between base->ours and base->theirs as line arrays
        const diffOurs = dmpLine.diff_linesToChars_(base, ours);
        const diffTheirs = dmpLine.diff_linesToChars_(base, theirs);
        // Actually, easier: compute diffs as arrays of line changes.
        const oursDiffs = dmpLine.diff_main(base, ours);
        const theirsDiffs = dmpLine.diff_main(base, theirs);
        // dmp.diff_cleanupSemantic(oursDiffs); theirsDiffs...

        // Now merge diffs: we need a state machine that walks base, applying changes from both.
        // If both modify same region -> conflict. Use simple algorithm: create array of base lines with change markers.

        // Represent each change as {start (base index), del count, insert lines}. Use diff_toDelta? No.
        // We'll convert diffs to patches and then combine. Already have patches.
        // Use patch-based conflict markers via dmp.patch_toText and parsing? simpler: use diff-match-patch's internal merge function.
        // There is no direct "merge with markers" in dmp. We'll implement:

        // 1. Build patch objects for ours and theirs.
        const patchesOurs = dmpLine.patch_make(base, ours);
        const patchesTheirs = dmpLine.patch_make(base, theirs);

        // 2. Combine patches: iterate through base lines, apply both patch sets, detect overlaps.
        const baseLinesArr = base.split('\n');
        let resultLines = [];
        let basePos = 0;
        let conflictCount = 0;

        // We'll use a simple line-by-line application using patches via dmp.patch_apply but merge manually.
        // Convert patches to change objects with start line and changes.
        function patchesToChanges(patches, baseText) {
          const changes = [];
          let currentLine = 0;
          for (const patch of patches) {
            // patch.start1 is char index; convert to line number roughly.
            const preText = baseText.substring(0, patch.start1);
            const startLine = preText.split('\n').length - 1;
            const length1 = patch.length1; // chars in base
            const baseSegment = baseText.substring(patch.start1, patch.start1 + length1);
            const baseSegLines = baseSegment.split('\n');
            const deleteLineCount = baseSegLines.length - 1; // lines to delete
            const diffs = patch.diffs;
            let insertLines = [];
            for (const [op, data] of diffs) {
              if (op === DIFF_INSERT || op === DIFF_EQUAL) {
                insertLines.push(...data.split('\n').slice(0, -1)); // remove trailing empty
              }
              // DIFF_DELETE is already accounted as deleteLineCount
            }
            changes.push({ startLine, deleteCount: deleteLineCount, insertLines });
          }
          return changes.sort((a,b) => a.startLine - b.startLine);
        }

        const oursChanges = patchesToChanges(patchesOurs, base);
        const theirsChanges = patchesToChanges(patchesTheirs, base);

        // Merge changes into base lines with conflict markers
        let lineIndex = 0;
        const totalLines = baseLinesArr.length;
        let iOurs = 0, iTheirs = 0;

        while (lineIndex < totalLines || iOurs < oursChanges.length || iTheirs < theirsChanges.length) {
          // Get next change from each (if exists)
          const nextOurs = iOurs < oursChanges.length ? oursChanges[iOurs] : null;
          const nextTheirs = iTheirs < theirsChanges.length ? theirsChanges[iTheirs] : null;

          if (!nextOurs && !nextTheirs) {
            // output remaining base lines
            resultLines.push(...baseLinesArr.slice(lineIndex));
            break;
          }

          const oursStart = nextOurs ? nextOurs.startLine : Infinity;
          const theirsStart = nextTheirs ? nextTheirs.startLine : Infinity;

          if (lineIndex < Math.min(oursStart, theirsStart)) {
            // copy unchanged base lines until next change
            resultLines.push(...baseLinesArr.slice(lineIndex, Math.min(oursStart, theirsStart)));
            lineIndex = Math.min(oursStart, theirsStart);
          }

          // Check overlap: if both changes start at same line or overlap
          if (nextOurs && nextTheirs && nextOurs.startLine === nextTheirs.startLine) {
            // Conflict: both modify same base region.
            conflictCount++;
            resultLines.push('<<<<<<< OURS');
            resultLines.push(...nextOurs.insertLines);
            resultLines.push('=======');
            resultLines.push(...nextTheirs.insertLines);
            resultLines.push('>>>>>>> THEIRS');
            // Advance lineIndex past the affected base region (delete counts might differ, use max)
            const maxDelete = Math.max(nextOurs.deleteCount, nextTheirs.deleteCount);
            lineIndex = nextOurs.startLine + maxDelete;
            iOurs++;
            iTheirs++;
          } else if (nextOurs && (!nextTheirs || nextOurs.startLine < nextTheirs.startLine)) {
            // Apply ours change, no conflict
            resultLines.push(...nextOurs.insertLines);
            lineIndex = nextOurs.startLine + nextOurs.deleteCount;
            iOurs++;
          } else if (nextTheirs) {
            // Apply theirs change
            resultLines.push(...nextTheirs.insertLines);
            lineIndex = nextTheirs.startLine + nextTheirs.deleteCount;
            iTheirs++;
          }
        }

        return { text: resultLines.join('\n'), conflictCount };
      }

      function updateConflictCountFromMerged() {
        const text = mergedEl.value;
        const conflicts = (text.match(/<<<<<<< OURS/g) || []).length;
        conflictCountSpan.textContent = `${conflicts} conflict(s)`;
        conflictCountSpan.className = conflicts > 0 ? 'conflict-indicator' : 'save-indicator';
      }

      // ----- Auto-accept best (ours preferred or smart heuristic) -----
      function autoAcceptBest() {
        const merged = mergedEl.value;
        if (!merged.includes('<<<<<<<')) {
          statusMsg.innerHTML = '<span>âœ¨</span> No conflicts to resolve.';
          return;
        }
        // Simple strategy: keep OURS block, discard THEIRS (or choose longer code? User can select)
        const resolved = merged.replace(
          /<<<<<<< OURS\n([\s\S]*?)=======\n([\s\S]*?)>>>>>>> THEIRS/g,
          (match, oursBlock, theirsBlock) => {
            // Heuristic: choose the one with more non-empty lines (more code) or user preference
            const oursLines = oursBlock.split('\n').filter(l => l.trim().length > 0).length;
            const theirsLines = theirsBlock.split('\n').filter(l => l.trim().length > 0).length;
            return oursLines >= theirsLines ? oursBlock : theirsBlock;
          }
        );
        mergedEl.value = resolved;
        updateConflictCountFromMerged();
        statusMsg.innerHTML = '<span>ðŸ§ </span> Auto-resolved using best-line heuristic.';
        saveToStorage();
      }

      // ----- Sample data -----
      function loadSample() {
        baseEl.value = `function greet(name) {
  return "Hello " + name;
}

function add(a, b) {
  return a + b;
}

// TODO: add multiply`;
        oursEl.value = `function greet(name, excited = false) {
  return excited ? "HELLO " + name + "!!!" : "Hello " + name;
}

function add(a, b) {
  return a + b;
}

function multiply(a, b) {
  return a * b;
}`;
        theirsEl.value = `function greet(name) {
  return "Hi " + name;
}

function add(a, b) {
  // add validation
  if (typeof a !== 'number' || typeof b !== 'number') return NaN;
  return a + b;
}

// multiply coming soon`;
        performMerge();
        statusMsg.innerHTML = '<span>ðŸ“¦</span> Sample versions loaded. Conflicts visible in merge.';
        saveToStorage();
      }

      // ----- copy merged -----
      function copyMerged() {
        navigator.clipboard.writeText(mergedEl.value).then(() => {
          statusMsg.innerHTML = '<span>ðŸ“‹</span> Merged code copied to clipboard!';
        }).catch(() => alert('Copy failed'));
      }

      // ----- clear all -----
      function clearAll() {
        baseEl.value = '';
        oursEl.value = '';
        theirsEl.value = '';
        mergedEl.value = '';
        conflictCountSpan.textContent = '0 conflicts';
        saveToStorage();
        statusMsg.innerHTML = '<span>ðŸ§¹</span> All editors cleared.';
      }

      // ----- event binding -----
      document.getElementById('btnMerge').addEventListener('click', performMerge);
      document.getElementById('btnClearAll').addEventListener('click', clearAll);
      document.getElementById('btnLoadSample').addEventListener('click', loadSample);
      document.getElementById('btnAcceptBest').addEventListener('click', autoAcceptBest);
      document.getElementById('btnCopyMerged').addEventListener('click', copyMerged);

      // Initial load
      loadFromStorage();
      if (!baseEl.value && !oursEl.value && !theirsEl.value) {
        // first visit hint
        mergedEl.value = '// Harmonized result will appear after merging.\n// Use "Load Sample" to see an example with conflicts.';
      } else {
        updateConflictCountFromMerged();
      }

      // Listen to merged editor manual edits and update conflict count
      mergedEl.addEventListener('input', () => {
        updateConflictCountFromMerged();
        saveToStorage();
      });

      console.log('ðŸ§¬ Codebase Harmonizer ready â€” await supplementary source versions for main integration.');
    })();
  </script>
</body>
</html>
